import './zodConfig';
import { z } from 'zod';
import {
  COLOR_IDS,
  HIGHLIGHT_KINDS,
  MAX_BANK_NAME_CHARS,
  MAX_COMMENT_CHARS,
  MAX_CONTEXT_CHARS,
  MAX_HEADING_CHARS,
  MAX_QUOTE_CHARS,
  MAX_TITLE_CHARS,
  MAX_URL_CHARS,
  PDF_TEXT_ALGORITHM,
  SCHEMA_VERSION,
  TEXT_ALGORITHM,
} from './constants';

/** Sortable opaque identifier (UUIDv7 generated by the storage layer). Validation is deliberately loose. */
export const Id = z.string().regex(/^[0-9A-Za-z_-]{8,64}$/, 'invalid id');
export const IsoDate = z.iso.datetime();
export const HttpUrl = z.url({ protocol: /^https?$/ }).max(MAX_URL_CHARS);

export const HighlightKind = z.enum(HIGHLIGHT_KINDS);
export const ColorId = z.enum(COLOR_IDS);
export const Priority = z.number().int().min(1).max(5);
/**
 * How a highlight came to be: a capture gesture, or 'import' for highlights read from a Markdown or
 * CSV file (their `customFields` say which, and that they still need review).
 */
export const CaptureMethod = z.enum(['toolbar', 'shortcut', 'context-menu', 'import']);
export const ResolveStatus = z.enum(['unchecked', 'resolved', 'changed', 'ambiguous', 'orphaned']);

export type Id = z.infer<typeof Id>;
export type HighlightKind = z.infer<typeof HighlightKind>;
export type ColorId = z.infer<typeof ColorId>;
export type Priority = z.infer<typeof Priority>;
export type CaptureMethod = z.infer<typeof CaptureMethod>;
export type ResolveStatus = z.infer<typeof ResolveStatus>;

const recordMeta = {
  schemaVersion: z.literal(SCHEMA_VERSION),
  createdAt: IsoDate,
  updatedAt: IsoDate,
  deletedAt: IsoDate.nullable(),
};

// ---------------------------------------------------------------------------------------------
// Anchors (W3C Web Annotation inspired). Offsets are in the sv-text-v1 stream, not raw DOM text.
// ---------------------------------------------------------------------------------------------

export const TextQuoteSelector = z.object({
  exact: z.string().min(1).max(MAX_QUOTE_CHARS),
  prefix: z.string().max(MAX_CONTEXT_CHARS),
  suffix: z.string().max(MAX_CONTEXT_CHARS),
});

export const TextPositionSelector = z
  .object({ start: z.number().int().min(0), end: z.number().int().min(1) })
  .refine((p) => p.end > p.start, 'end must be after start');

export const HtmlAnchorSet = z.object({
  type: z.literal('html'),
  textAlgorithm: z.literal(TEXT_ALGORITHM),
  textQuote: TextQuoteSelector,
  textPosition: TextPositionSelector,
  /** Hint only. Never authoritative: DOM structure changes freely between visits. */
  structuralPath: z.string().max(1024).nullable(),
  /** Non-cryptographic hash of the whole document text stream at capture time (change detection). */
  contentSignature: z.string().max(32),
  /** Length of the text stream at capture time. */
  documentTextLength: z.number().int().min(0),
});
export type HtmlAnchorSet = z.infer<typeof HtmlAnchorSet>;

/** Normalised rectangle on a PDF page: 0..1 of the page box, origin top-left, rotation 0. */
export const PdfRect = z.object({
  x: z.number().min(0).max(1),
  y: z.number().min(0).max(1),
  w: z.number().min(0).max(1),
  h: z.number().min(0).max(1),
});
export type PdfRect = z.infer<typeof PdfRect>;

/**
 * Anchor inside the extension-owned PDF reader (ADR-006). Field names that overlap HtmlAnchorSet
 * (textQuote, textPosition, contentSignature, documentTextLength) keep their meaning but refer to
 * the page text stream of ONE page, so generic code (duplicate detection, ordering) works on both.
 */
export const PdfAnchorSet = z.object({
  type: z.literal('pdf'),
  textAlgorithm: z.literal(PDF_TEXT_ALGORITHM),
  /** Content fingerprint of the document (sha-256 hex of the bytes, or PDF.js fingerprint fallback). */
  documentFingerprint: z.string().min(8).max(128),
  /** 1-based page number. */
  pageNumber: z.number().int().min(1),
  /** Page rotation (degrees, 0/90/180/270) when the rects were captured. */
  rotation: z.number().int(),
  /** Highlight rectangles, one per selected line box, in reading order. */
  rects: z.array(PdfRect).min(1).max(256),
  textQuote: TextQuoteSelector,
  /** Offsets within this page's text stream. */
  textPosition: TextPositionSelector,
  contentSignature: z.string().max(32),
  /** Length of the page text stream at capture time. */
  documentTextLength: z.number().int().min(0),
});
export type PdfAnchorSet = z.infer<typeof PdfAnchorSet>;

export const AnchorSet = z.discriminatedUnion('type', [HtmlAnchorSet, PdfAnchorSet]);
export type AnchorSet = z.infer<typeof AnchorSet>;

// ---------------------------------------------------------------------------------------------
// Persisted records
// ---------------------------------------------------------------------------------------------

export const Bank = z.object({
  id: Id,
  ...recordMeta,
  name: z.string().trim().min(1).max(MAX_BANK_NAME_CHARS),
  color: ColorId,
  position: z.number(),
  isInbox: z.boolean(),
});
export type Bank = z.infer<typeof Bank>;

export const Source = z.object({
  id: Id,
  ...recordMeta,
  /** 'pdf' sources are keyed by `documentId` (urlKey is `pdf:<documentId>`), see packages/storage. */
  type: z.enum(['web', 'pdf']),
  /** Set for type 'pdf': id of the `documents` row (content fingerprint of the file). */
  documentId: Id.optional(),
  /** Normalised identity of the page (canonical URL when trustworthy, else the page URL). */
  urlKey: z.string().max(MAX_URL_CHARS),
  /** Normalised URL the user actually visited; secondary lookup key. */
  visitedKey: z.string().max(MAX_URL_CHARS),
  originalUrl: HttpUrl,
  canonicalUrl: HttpUrl.nullable(),
  host: z.string().max(253),
  title: z.string().max(MAX_TITLE_CHARS),
});
export type Source = z.infer<typeof Source>;

/** User-defined metadata on a highlight (PRD "Custom fields"). Keys and values are plain text/numbers. */
export const MAX_CUSTOM_FIELDS = 32;
export const MAX_CUSTOM_FIELD_KEY_CHARS = 64;
export const MAX_CUSTOM_FIELD_VALUE_CHARS = 500;

export const CustomFieldKey = z
  .string()
  .min(1)
  .max(MAX_CUSTOM_FIELD_KEY_CHARS)
  .refine(
    (key) =>
      key === key.trim() &&
      key !== '__proto__' &&
      ![...key].some((ch) => ch.charCodeAt(0) < 0x20 || ch.charCodeAt(0) === 0x7f),
    'invalid custom field name',
  );
export const CustomFieldValue = z.union([
  z.string().max(MAX_CUSTOM_FIELD_VALUE_CHARS),
  z.number(),
  z.boolean(),
]);
export const CustomFields = z
  .record(CustomFieldKey, CustomFieldValue)
  .refine((r) => Object.keys(r).length <= MAX_CUSTOM_FIELDS, `at most ${MAX_CUSTOM_FIELDS} fields`);
export type CustomFields = z.infer<typeof CustomFields>;

export const Highlight = z.object({
  id: Id,
  ...recordMeta,
  sourceId: Id,
  /** Immutable source provenance. Never edited after capture; user interpretation goes in userComment. */
  exactQuote: z.string().min(1).max(MAX_QUOTE_CHARS),
  normalizedQuote: z.string().max(MAX_QUOTE_CHARS),
  quoteHash: z.string().length(64),
  anchorSet: AnchorSet,
  kind: HighlightKind,
  color: ColorId,
  priority: Priority,
  userComment: z.string().max(MAX_COMMENT_CHARS),
  headingContext: z.string().max(MAX_HEADING_CHARS).nullable(),
  captureMethod: CaptureMethod,
  capturedAt: IsoDate,
  resolveStatus: ResolveStatus,
  resolveConfidence: z.number().min(0).max(1).nullable(),
  lastResolvedAt: IsoDate.nullable(),
  /**
   * Immutable provenance of the capture: the address (credentials removed) and title of the page
   * as it was when the quote was saved. A Source can span address variants; this does not. Absent
   * on rows written before these existed. Not indexed, so no Dexie version bump.
   */
  capturedUrl: HttpUrl.optional(),
  capturedTitle: z.string().max(MAX_TITLE_CHARS).optional(),
  /** User metadata (modality, system, exam frequency ...). Never part of the immutable provenance. */
  customFields: CustomFields.optional(),
});
export type Highlight = z.infer<typeof Highlight>;

/** Many-to-many membership so one highlight can live in several banks without duplication. */
export const HighlightBank = z.object({
  highlightId: Id,
  bankId: Id,
  /** Reserved for the Phase 2 folder hierarchy. Always null in schema v1. */
  folderId: Id.nullable(),
  addedAt: IsoDate,
});
export type HighlightBank = z.infer<typeof HighlightBank>;

// ---------------------------------------------------------------------------------------------
// Views passed across the message boundary (never raw DB rows to untrusted contexts)
// ---------------------------------------------------------------------------------------------

export const HighlightView = z.object({
  id: Id,
  sourceId: Id,
  exactQuote: z.string(),
  anchorSet: AnchorSet,
  kind: HighlightKind,
  color: ColorId,
  priority: Priority,
  userComment: z.string(),
  headingContext: z.string().nullable(),
  bankIds: z.array(Id),
  capturedAt: IsoDate,
  resolveStatus: ResolveStatus,
  resolveConfidence: z.number().nullable(),
});
export type HighlightView = z.infer<typeof HighlightView>;

export const PageInfo = z.object({
  url: HttpUrl,
  canonicalUrl: HttpUrl.nullable(),
  title: z.string().max(MAX_TITLE_CHARS),
});
export type PageInfo = z.infer<typeof PageInfo>;
